(() => {
  'use strict';
  const KEY='lapka-prototype-v1';
  const now=new Date();
  const iso=(d)=>{const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};
  const addDays=(date,n)=>{const d=new Date(`${date}T12:00:00`);d.setDate(d.getDate()+n);return iso(d)};
  const today=iso(now);
  const uid=()=>Math.random().toString(36).slice(2,9);
  const esc=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const demoState=()=>({
    version:1,activePetId:'pet-luna',pets:[{id:'pet-luna',name:'Луна',species:'Собака',breed:'Метис',birthDate:'2022-04-18',note:'Любит долгие прогулки и мягкие игрушки.',emoji:'🐕',demo:true}],
    events:[{id:'event-demo',petId:'pet-luna',title:'Обработка от блох и клещей',date:addDays(today,3),note:'Демо-напоминание из примера. Проверьте средство и график с ветеринаром.',repeatDays:30,done:false,demo:true},{id:'event-walk',petId:'pet-luna',title:'Прогулка в парке',date:today,note:'Вечерняя прогулка',repeatDays:0,done:false,demo:true}],
    foodEntries:[{id:'food-demo',petId:'pet-luna',date:today,food:'Утренний корм',note:'Демонстрационная запись',demo:true}],
    documents:[],photos:[],settings:{onboardingDone:false,city:'',profileVisible:false,showCity:false,showApprox:false,allowMessages:false},
    community:{blocked:[],requests:[],reports:[],messages:[]}
  });
  let state;try{state=JSON.parse(localStorage.getItem(KEY))||demoState()}catch{state=demoState()}
  if(!state.settings) state.settings=demoState().settings;
  if(!state.community) state.community=demoState().community;
  if(!Array.isArray(state.pets))state.pets=[];
  let route='home', subroute='timeline', modal=null, toastTimer=null;
  const app=document.getElementById('app'), modalRoot=document.getElementById('modal-root'), toastEl=document.getElementById('toast');
  const fileDB=(()=>{let dbPromise;function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('lapka-local-files',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return dbPromise}return{put:async(id,blob)=>{const d=await db();return new Promise((res,rej)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').put(blob,id);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})},get:async(id)=>{const d=await db();return new Promise((res,rej)=>{const r=d.transaction('files').objectStore('files').get(id);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})},del:async(id)=>{const d=await db();return new Promise((res,rej)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').delete(id);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}}})();
  function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){notify('Не удалось сохранить изменения. Возможно, закончилось место.');console.error(e)}}
  const petById=id=>state.pets.find(p=>p.id===id);
  const currentPet=()=>petById(state.activePetId)||state.pets[0]||null;
  const fmtDate=(s,opts={day:'numeric',month:'long'})=>{if(!s)return 'Дата не указана';const d=new Date(`${s}T12:00:00`);return new Intl.DateTimeFormat('ru-RU',opts).format(d)};
  const dayNum=s=>new Date(`${s}T12:00:00`).getDate();
  function notify(text){toastEl.textContent=text;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2600)}
  const navItems=[['home','⌂','Главная'],['pets','🐾','Питомцы'],['care','♡','Забота'],['community','☻','Сообщество'],['more','•••','Ещё']];
  const moreItems=[['places','⌖','Петфрендли места'],['knowledge','▤','База знаний'],['documents','▣','Архив документов'],['gallery','▧','Галерея'],['templates','▤','Шаблоны'],['settings','⚙','Настройки']];
  const routeLabel=()=>({home:'Главная',pets:'Питомцы',care:'Забота',community:'Сообщество',more:'Ещё',places:'Петфрендли места',knowledge:'База знаний',documents:'Архив документов',gallery:'Галерея',templates:'Полезные шаблоны',settings:'Настройки',vet:'Чат с врачом',food:'Проверка продуктов'}[route]||'Лапка');
  function navButton(item, mobile=false){const [id,icon,label]=item;return `<button class="nav-item ${route===id?'active':''}" data-route="${id}" aria-label="${label}"><span class="nav-icon" aria-hidden="true">${icon}</span><span>${label}</span></button>`}
  function shell(content){const desktop=navItems.slice(0,4).map(x=>navButton(x)).join('')+`<div class="nav-label">Уход и сервисы</div>`+[['vet','✚','Чат с врачом'],['food','◉','Опасные продукты'],...moreItems].map(x=>navButton(x)).join('');const mobile=[navItems[0],navItems[1],navItems[2],navItems[3],['more','•••','Ещё']].map(x=>`<button class="${route===x[0]?'active':''}" data-route="${x[0]}" aria-label="${x[2]}"><span class="nav-icon">${x[1]}</span><span>${x[2]}</span></button>`).join('');return `<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">🐾</div><div><div class="brand-name">Лапка</div><div class="brand-sub">забота рядом</div></div></div><div class="nav-label">Пространство</div><nav class="side-nav">${desktop}</nav><div class="sidebar-bottom"><div class="privacy-mini"><strong>🔒 Всё пока только у вас</strong><p>Демо работает в этом браузере. Профиль сообщества выключен.</p></div><div class="user-mini"><div class="avatar">🙂</div><div><div class="user-name">Мой профиль</div><div class="user-tag">Локальное демо</div></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb">Лапка <span style="color:#c4cbc5"> / </span> ${esc(routeLabel())}</div><div class="top-actions"><span class="top-date">${fmtDate(today,{weekday:'short',day:'numeric',month:'long'})}</span>${state.pets.length?`<select class="top-pet-select" id="top-pet-select" aria-label="Выбрать питомца">${state.pets.map(p=>`<option value="${esc(p.id)}" ${p.id===currentPet()?.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`:''}<button class="icon-button" data-route="settings" aria-label="Настройки">⚙</button></div></header><div class="content">${content}</div></main><nav class="mobile-nav" aria-label="Основная навигация">${mobile}</nav></div>`}
  function title(eyebrow,h1,sub='',action=''){return `<div class="page-title-row"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${h1}</h1>${sub?`<p class="page-subtitle">${sub}</p>`:''}</div>${action}</div>`}
  function demoBanner(text='Демо-режим: данные сохраняются только в этом браузере. Реальные сервисы не подключены.'){return `<div class="demo-banner"><span>ⓘ</span><span>${text}</span></div>`}
  function empty(icon,heading,desc,button=''){return `<div class="empty-state"><div class="empty-icon">${icon}</div><h3>${heading}</h3><p>${desc}</p>${button}</div>`}
  function quick(icon,tint,label,desc,dest){return `<button class="quick-card" data-route="${dest}"><span class="quick-icon ${tint}">${icon}</span><b>${label}</b><small>${desc}</small></button>`}
  function eventCard(e,compact=false){const p=petById(e.petId);return `<div class="event-row"><div class="event-date"><b>${dayNum(e.date)}</b><small>${fmtDate(e.date,{month:'short'})}</small></div><div class="event-info"><b>${esc(e.title)} ${e.done?'<span class="tag green">Готово</span>':''}</b><p>${esc(p?.name||'Питомец')} · ${esc(e.note||'Без заметки')}${e.repeatDays?` · повтор: ${e.repeatDays} дн.`:''}${e.demo?` · демо`:''}</p></div><div class="event-actions">${!e.done?`<button class="btn btn-soft btn-small" data-action="event-done" data-id="${e.id}" aria-label="Завершить">✓</button>`:''}<button class="btn btn-secondary btn-small" data-action="edit-event" data-id="${e.id}" aria-label="Изменить">⋯</button></div></div>`}
  function homePage(){const p=currentPet();const upcoming=state.events.filter(e=>e.petId===p?.id&&!e.done).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3);return `${demoBanner()}<section class="hero"><div class="hero-copy"><div class="eyebrow">Ваше пространство заботы</div><h1>Хвост счастлив —<br>день удался 🐾</h1><p>Всё важное о питомце — в одном тёплом месте. Планируйте уход, сохраняйте воспоминания и находите ответы.</p><button class="btn btn-primary" data-route="care">Открыть таймлайн <span>→</span></button></div>${p?`<div class="pet-switcher"><div class="pet-emoji">${esc(p.emoji||'🐾')}</div><div><small>Сейчас выбрана</small><select id="hero-pet-select" aria-label="Выбрать питомца">${state.pets.map(x=>`<option value="${esc(x.id)}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><button class="btn btn-quiet" data-route="pets" aria-label="Управлять питомцами">↗</button></div>`:`<button class="btn btn-primary" data-action="add-pet">＋ Добавить питомца</button>`}</section><div class="section-heading"><h2>Быстрые действия</h2><span class="tag">Для ${esc(p?.name||'питомца')}</span></div><div class="quick-grid">${quick('✚','tint-peach','Чат с врачом','Демо, без специалиста','vet')}${quick('◉','tint-lav','Опасные продукты','Проверить продукт','food')}${quick('⌖','tint-blue','Петфрендли места','Каталог-пример','places')}${quick('♡','tint-mint','Профиль питомца','Сведения и настройки','pets')}${quick('▤','tint-lime','База знаний','Статьи-черновики','knowledge')}${quick('▣','tint-peach','Архив документов','Только на устройстве','documents')}${quick('◷','tint-blue','Таймлайн','События и напоминания','care')}${quick('♧','tint-lav','Дневник питания','Записи о рационе','care')}${quick('▧','tint-pink','Галерея','Фото питомца','gallery')}${quick('✉','tint-lime','Полезные шаблоны','Чек-листы и заметки','templates')}${quick('☻','tint-mint','Сообщество','Добровольное демо','community')}</div><div class="section-heading"><h2>Ближайшие события</h2><button data-route="care">Весь таймлайн →</button></div><div class="card"><div class="event-list">${upcoming.length?upcoming.map(e=>eventCard(e,true)).join(''):empty('◷','Пока нет событий','Добавьте напоминание, чтобы не забыть о важном.',`<button class="btn btn-primary btn-small" data-action="add-event">Создать событие</button>`)}</div></div><p class="footer-note">Демо-данные питомца и напоминаний можно изменить или удалить. Приложение не даёт ветеринарных назначений.</p>`}
  function petsPage(){return `${title('Профили','Мои питомцы','Создавайте отдельные профили и переключайтесь между ними.',`<button class="btn btn-primary" data-action="add-pet">＋ Добавить питомца</button>`)}${demoBanner('Профили и записи хранятся локально в браузере. Добавленные изображения и документы не отправляются на сервер.')}${state.pets.length?`<div class="pet-grid">${state.pets.map(p=>`<article class="card pet-card ${p.id===currentPet()?.id?'selected':''}"><div class="pet-avatar">${esc(p.emoji||'🐾')}</div><h3>${esc(p.name)} ${p.id===currentPet()?.id?'<span class="tag green">Выбран</span>':''}</h3><p>${esc(p.species||'Питомец')}${p.breed?` · ${esc(p.breed)}`:''}<br>${p.birthDate?`Дата рождения: ${fmtDate(p.birthDate,{day:'numeric',month:'long',year:'numeric'})}`:'Дата рождения не указана'}</p>${p.note?`<p>${esc(p.note)}</p>`:''}<div class="card-controls"><button class="btn btn-soft btn-small" data-action="select-pet" data-id="${p.id}">Выбрать</button><button class="btn btn-secondary btn-small" data-action="edit-pet" data-id="${p.id}">Изменить</button><button class="btn btn-quiet btn-small" data-action="delete-pet" data-id="${p.id}">Удалить</button></div></article>`).join('')}</div>`:empty('🐾','Питомцев пока нет','Добавьте профиль, чтобы вести таймлайн и дневник питания.',`<button class="btn btn-primary" data-action="add-pet">Добавить питомца</button>`)}`}
  function carePage(){const tab=subroute==='food'?'food':'timeline';const p=currentPet();let body='';if(tab==='timeline'){const list=state.events.filter(e=>!p||e.petId===p.id).sort((a,b)=>a.date.localeCompare(b.date));body=`<div class="section-heading" style="margin-top:0"><h2>События ${p?`· ${esc(p.name)}`:''}</h2><button class="btn btn-primary btn-small" data-action="add-event">＋ Событие</button></div><div class="card"><div class="event-list">${list.length?list.map(e=>eventCard(e)).join(''):empty('◷','Таймлайн пуст','Создайте напоминание или запись о событии.',`<button class="btn btn-primary btn-small" data-action="add-event">Создать событие</button>`)}</div></div><div class="notice">Напоминания — это пользовательские записи, а не медицинские назначения. Интервал обработки и выбор средства обсудите с ветеринаром.</div>`}else{const entries=state.foodEntries.filter(e=>!p||e.petId===p.id).sort((a,b)=>b.date.localeCompare(a.date));body=`<div class="section-heading" style="margin-top:0"><h2>Дневник ${p?`· ${esc(p.name)}`:''}</h2><button class="btn btn-primary btn-small" data-action="add-food">＋ Запись</button></div><div class="grid" style="gap:10px">${entries.length?entries.map(e=>`<div class="list-card"><div class="list-icon">🥣</div><div class="list-main"><b>${esc(e.food)}</b><p>${fmtDate(e.date,{day:'numeric',month:'long',year:'numeric'})} · ${esc(petById(e.petId)?.name||'Питомец')}${e.note?` · ${esc(e.note)}`:''}${e.demo?' · демо':''}</p></div><div class="list-actions"><button class="btn btn-secondary btn-small" data-action="edit-food" data-id="${e.id}">Изменить</button><button class="btn btn-quiet btn-small" data-action="delete-food" data-id="${e.id}">Удалить</button></div></div>`).join(''):empty('🥣','Записей пока нет','Добавьте корм или продукт, чтобы вести дневник.')}</div>`}return `${title('Уход и привычки','Забота о питомце','События, напоминания и дневник питания — отдельно для каждого питомца.')}${demoBanner()}<div class="subnav"><button class="${tab==='timeline'?'active':''}" data-sub="timeline">◷ Таймлайн</button><button class="${tab==='food'?'active':''}" data-sub="food">♧ Дневник питания</button></div>${body}`}
  function foodPage(){return `${title('Проверка продукта','Можно ли собаке?','Поиск по демонстрационному справочнику. Не заменяет консультацию ветеринара.')}${demoBanner('Демо-база неполная и не подключена к ветеринарным источникам. Не используйте результат как медицинское решение.') }<div class="card"><label class="label" for="food-search">Название продукта</label><form id="food-check-form" class="food-check"><input id="food-search" class="input" placeholder="Например, колбаса" autocomplete="off"/><button class="btn btn-primary">Проверить</button></form><div id="food-result"></div><div class="notice">Если питомец съел неизвестный продукт или у него появились симптомы, свяжитесь с ветеринарной клиникой. Не ждите ответа демо-справочника.</div></div><div class="section-heading"><h2>Популярный пример</h2></div><button class="list-card" data-food-example="колбаса" style="width:100%;text-align:left"><span class="list-icon">🌭</span><span class="list-main"><b>Колбаса</b><p>Пример осторожного предупреждения из требований прототипа.</p></span><span>→</span></button>`}
  function vetPage(){return `${title('Отдельный канал помощи','Чат с врачом','Интерфейс подготовлен, но ветеринарная служба не подключена.')}${demoBanner('Это не лицензированный специалист и не автоматическая диагностика. Сообщения не отправляются.') }<div class="card" style="max-width:720px"><div class="profile-hero"><div class="profile-art">🩺</div><div><span class="tag orange">Сервис не подключён</span><h2 style="font-size:17px;margin-top:8px">Здесь пока нет врача</h2><p class="page-subtitle" style="margin-top:5px">Не отправляйте сюда персональные или медицинские данные: чат работает только как демонстрация интерфейса.</p></div></div><hr class="hr"><div class="notice" style="background:#fff2ea;color:#875a3b"><b>Если состояние питомца экстренное</b>, немедленно позвоните в ближайшую ветеринарную клинику или обратитесь за неотложной помощью. Этот прототип не ставит диагнозы и не назначает лекарства.</div><button class="btn btn-secondary" style="margin-top:15px" data-action="vet-demo">Посмотреть демо-переписку</button></div>`}
  const demoPeople=[{id:'person-1',name:'Саша и Боня',city:'Город не указан',near:'пример профиля',emoji:'🐶',about:'Любят спокойные прогулки и игры с мячом.'},{id:'person-2',name:'Миша и Рэй',city:'Город не указан',near:'пример профиля',emoji:'🦮',about:'Ищут идеи для совместных прогулок.'},{id:'person-3',name:'Аня и Плюша',city:'Город не указан',near:'пример профиля',emoji:'🐕‍🦺',about:'Демо-карточка сообщества.'}];
  function communityPage(){const settings=state.settings;const visible=demoPeople.filter(p=>!state.community.blocked.includes(p.id));return `${title('Добровольное общение','Сообщество','Знакомства и чаты — только после согласия. В этой сборке сообщество не подключено.')}${demoBanner('Все карточки ниже — вымышленные примеры. Они не соответствуют реальным людям и не могут получать сообщения.') }<div class="two-col"><section><div class="card"><div style="display:flex;align-items:center;justify-content:space-between;gap:10px"><div><h2 style="font-size:15px">Профиль в поиске</h2><p class="page-subtitle" style="margin-top:6px">По умолчанию выключен. В демо переключатель ничего не публикует.</p></div><input class="switch" type="checkbox" data-setting="profileVisible" ${settings.profileVisible?'checked':''} aria-label="Показывать мой профиль в поиске"></div><div class="notice">Точная геолокация не показывается. Не сохраняются GPS-точка, адрес или история перемещений.</div><button class="btn btn-secondary btn-small" style="margin-top:12px" data-route="settings">Настроить приватность</button></div><div class="section-heading"><h2>Примеры карточек</h2><span class="tag">Демо-профили</span></div><div class="grid" style="gap:10px">${visible.length?visible.map(p=>`<div class="card community-card"><div class="community-avatar">${p.emoji}</div><div class="info"><b>${esc(p.name)} <span class="tag">пример</span></b><span>${esc(p.city)} · ${esc(p.near)}<br>${esc(p.about)}</span></div><button class="btn btn-soft btn-small" data-action="community-request" data-id="${p.id}">${state.community.requests.includes(p.id)?'Запрос отправлен':'Поздороваться'}</button><button class="btn btn-quiet btn-small" data-action="community-block" data-id="${p.id}" title="Скрыть карточку">⊘</button></div>`).join(''):empty('☻','Список скрыт','Все демонстрационные карточки скрыты.')}</div></section><aside><div class="card"><h2 style="font-size:14px">Правила безопасного общения</h2><div class="notice">Не публикуйте адрес, номер телефона, расписание прогулок или документы. Для первой встречи выбирайте общественное место и договаривайтесь самостоятельно.</div><hr class="hr"><button class="btn btn-secondary btn-small" data-action="community-report">Пожаловаться на пример</button><p class="footer-note">В рабочем сервисе нужны серверная авторизация, защита от спама, процесс модерации и проверенные настройки видимости.</p></div></aside></div>`}
  function placesPage(){const cards=[['🌳','Зелёная прогулочная зона','Пример карточки · адрес не задан'],['☕','Кафе с питомцами','Демонстрационная запись · часы не подтверждены'],['🐾','Площадка для прогулок','Не является реальным местом']];return `${title('Гулять вместе','Петфрендли места','Каталог-пример: реальные точки, адреса и режим работы не подключены.')}${demoBanner('Не используйте карточки как навигацию: это вымышленные примеры без реальных адресов.') }<div class="filter-row"><div class="searchbar"><span>⌕</span><input id="place-search" placeholder="Поиск по демо-карточкам" /></div><span class="tag">Геолокация выключена</span></div><div class="grid grid-3" id="place-grid">${cards.map(c=>`<article class="card article-card place-item" data-search="${esc(c[1].toLowerCase())}"><div class="article-art">${c[0]}</div><h3>${c[1]}</h3><p>${c[2]}</p><div class="article-meta">Пример · точка не подтверждена</div></article>`).join('')}</div><p class="footer-note">В реальной версии источники мест, лицензии на изображения, часы работы и доступность необходимо подтверждать.</p>`}
  const articles=[['✂️','Бережный груминг','Как подготовить питомца к спокойному уходу.','Материал-черновик · нужна проверка специалистом'],['👁️','Уход за глазами','Общие вопросы гигиены и когда стоит обратиться к врачу.','Справочная карточка · не медицинская рекомендация'],['🧰','Аптечка питомца','Шаблон списка для обсуждения с ветеринаром.','Материал-черновик · не инструкция по лечению'],['🚶','Прогулки','Идеи для безопасных и комфортных прогулок.','Общие заметки · требуется редактура'],['🐕','Акита-ину','Краткая карточка породы. Индивидуальные особенности различаются.','Источники не подключены · черновик'],['🐕‍🦺','Алабай','Краткая карточка породы. Индивидуальные особенности различаются.','Источники не подключены · черновик']];
  function knowledgePage(){return `${title('Полезное рядом','База знаний','Карточки для чтения. Содержимое требует фактчекинга и ветеринарной редакции.')}${demoBanner('Статьи — черновики, не являются медицинскими рекомендациями. Проверенные источники и даты обновления не подключены.') }<div class="filter-row"><div class="searchbar"><span>⌕</span><input id="knowledge-search" placeholder="Найти статью" /></div><span class="tag">6 демо-карточек</span></div><div class="grid grid-3" id="knowledge-grid">${articles.map((a,i)=>`<article class="card article-card knowledge-item" data-index="${i}" data-search="${esc(a[1].toLowerCase())}"><div class="article-art">${a[0]}</div><h3>${a[1]}</h3><p>${a[2]}</p><div class="article-meta">${a[3]}</div></article>`).join('')}</div>`}
  function documentsPage(){const items=state.documents.filter(d=>!currentPet()||d.petId===currentPet().id);return `${title('Личное хранилище','Архив документов','Файлы остаются в IndexedDB этого браузера и никуда не загружаются.',`<button class="btn btn-primary" data-action="add-document">＋ Добавить файл</button>`)}${demoBanner('Локальное хранилище не является резервной копией. При очистке данных браузера файлы могут быть удалены.') }<div class="grid" style="gap:10px">${items.length?items.map(d=>`<div class="list-card"><div class="list-icon">▣</div><div class="list-main"><b>${esc(d.name)}</b><p>${esc(petById(d.petId)?.name||'Питомец')} · ${fmtDate(d.date,{day:'numeric',month:'long',year:'numeric'})} · ${esc(d.kind||'Документ')} · ${Math.max(1,Math.round((d.size||0)/1024))} КБ</p></div><div class="list-actions"><button class="btn btn-soft btn-small" data-action="download-file" data-id="${d.fileId}" data-name="${esc(d.name)}">Открыть</button><button class="btn btn-quiet btn-small" data-action="delete-document" data-id="${d.id}" data-file="${d.fileId}">Удалить</button></div></div>`).join(''):empty('▣','Архив пуст','Добавьте документ, чтобы хранить его в этом браузере.',`<button class="btn btn-primary btn-small" data-action="add-document">Добавить файл</button>`)}</div>`}
  function galleryPage(){const items=state.photos.filter(d=>!currentPet()||d.petId===currentPet().id);return `${title('Тёплые моменты','Галерея','Приватные фотографии выбранного питомца, сохранённые локально.',`<button class="btn btn-primary" data-action="add-photo">＋ Добавить фото</button>`)}${demoBanner('Фото доступны только в текущем браузере и не публикуются в сообществе.') }${items.length?`<div class="photo-grid">${items.map(x=>`<div class="photo-tile"><img data-local-file="${x.fileId}" alt="${esc(x.name)}"><span class="photo-fallback">🐾</span><button class="btn btn-danger btn-small" data-action="delete-photo" data-id="${x.id}" data-file="${x.fileId}" aria-label="Удалить фото">×</button></div>`).join('')}</div>`:empty('▧','Здесь появятся фотографии','Добавьте снимок, чтобы собрать приватную галерею.',`<button class="btn btn-primary btn-small" data-action="add-photo">Добавить фото</button>`)}`}
  function templatesPage(){const ts=[['🩺','Подготовка к визиту к ветеринару','Запишите вопросы и наблюдения для обсуждения со специалистом.','Вопросы · даты · заметки'],['🧳','Список для поездки','Проверьте документы и привычные вещи питомца перед дорогой.','Документы · корм · контакты клиники'],['🐾','Знакомство на прогулке','Небольшой план, чтобы договориться о безопасной встрече.','Общественное место · время · пожелания'],['📝','Профиль питомца','Соберите основные сведения о питомце в одном месте.','Имя · особенности · контакты владельца (приватно)']];return `${title('Готовые заготовки','Полезные шаблоны','Небольшие списки, которые можно заполнить под себя.')}${demoBanner('Шаблоны — вспомогательные заметки. Медицинские решения принимайте вместе с ветеринаром.') }<div class="grid grid-2">${ts.map((t,i)=>`<article class="card article-card template-item" data-template="${i}"><div class="list-icon" style="margin-bottom:14px">${t[0]}</div><h3>${t[1]}</h3><p style="font-size:11px;color:var(--muted);line-height:1.6">${t[2]}</p><div class="article-meta">Поля: ${t[3]}</div><button class="btn btn-soft btn-small" style="margin-top:13px" data-action="open-template" data-id="${i}">Открыть шаблон</button></article>`).join('')}</div>`}
  function settingsPage(){const s=state.settings;return `${title('Ваш контроль','Настройки приватности','Профиль, геолокация и данные по умолчанию остаются приватными.')}${demoBanner('Настройки ниже показывают локальное поведение прототипа; серверной публикации не происходит.') }<div class="two-col"><div class="card"><h2 style="font-size:15px;margin-bottom:5px">Обнаружение в сообществе</h2><p class="page-subtitle" style="margin:0 0 8px">Публичный поиск отключён, пока вы явно не включите его.</p>${[['profileVisible','Показывать мой профиль в поиске','Только выбранные публичные сведения.'],['showCity','Показывать город/регион','Точная геолокация не отображается.'],['showApprox','Показывать примерную близость','Расстояние не выдаётся как точная координата.'],['allowMessages','Разрешить запросы на общение','В демо сообщения не отправляются.']].map(x=>`<div class="switch-row"><div><b>${x[1]}</b><p>${x[2]}</p></div><input class="switch" type="checkbox" data-setting="${x[0]}" ${s[x[0]]?'checked':''} aria-label="${x[1]}"></div>`).join('')}<div class="field" style="margin-top:16px"><label class="label" for="manual-city">Город (вводится вручную)</label><input class="input" id="manual-city" value="${esc(s.city||'')}" placeholder="Необязательно" /><div class="help">Необязательно. Не сохраняем точку GPS и историю перемещений.</div><button class="btn btn-secondary btn-small" style="margin-top:8px" data-action="save-city">Сохранить город</button></div><button class="btn btn-secondary btn-small" data-action="request-location">Запросить геолокацию</button></div><div class="card"><h2 style="font-size:15px">Данные на устройстве</h2><p class="page-subtitle">Экспортируйте локальные записи или удалите демонстрационные данные.</p><div class="grid" style="margin-top:18px"><button class="btn btn-soft" data-action="export-data">↓ Экспортировать данные JSON</button><button class="btn btn-secondary" data-action="reset-data">Сбросить приложение</button></div><div class="notice">В этой сборке нет аккаунта, сервера или синхронизации. Удаление данных браузера может удалить файлы.</div><hr class="hr"><h3 style="font-size:12px">Безопасность встреч</h3><p class="page-subtitle">Не сообщайте домашний адрес и выбирайте общественное место для первой встречи.</p><button class="btn btn-secondary btn-small" data-action="community-rules">Правила сообщества</button></div></div>`}
  function morePage(){return `${title('Разделы','Всё для питомца','Библиотека, файлы и настройки в одном месте.')}<div class="quick-grid">${quick('⌖','tint-blue','Петфрендли места','Демо-каталог','places')}${quick('▤','tint-lime','База знаний','Черновики статей','knowledge')}${quick('▣','tint-peach','Архив документов','Локальное хранение','documents')}${quick('▧','tint-pink','Галерея','Локальные фото','gallery')}${quick('✉','tint-lav','Полезные шаблоны','Чек-листы','templates')}${quick('⚙','tint-mint','Настройки','Приватность и данные','settings')}${quick('✚','tint-peach','Чат с врачом','Не подключён','vet')}${quick('◉','tint-lav','Опасные продукты','Демо-справочник','food')}</div>`}
  function render(){let content='';switch(route){case'home':content=homePage();break;case'pets':content=petsPage();break;case'care':content=carePage();break;case'food':content=foodPage();break;case'vet':content=vetPage();break;case'community':content=communityPage();break;case'places':content=placesPage();break;case'knowledge':content=knowledgePage();break;case'documents':content=documentsPage();break;case'gallery':content=galleryPage();break;case'templates':content=templatesPage();break;case'settings':content=settingsPage();break;default:content=morePage();route='more'}app.innerHTML=shell(content);renderModal();hydrateImages();}
  async function hydrateImages(){document.querySelectorAll('img[data-local-file]').forEach(async img=>{try{const b=await fileDB.get(img.dataset.localFile);if(b){img.src=URL.createObjectURL(b);img.onload=()=>img.parentElement.querySelector('.photo-fallback')?.remove()}}catch{}})}
  function openModal(titleText,desc,body,opts={}){modal={title:titleText,desc,body,wide:!!opts.wide,footer:opts.footer||''};renderModal();setTimeout(()=>modalRoot.querySelector('input,select,textarea,button')?.focus(),30)}
  function closeModal(){modal=null;renderModal()}
  function renderModal(){if(!modal){modalRoot.innerHTML='';return}modalRoot.innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal ${modal.wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><div><h2 id="modal-title">${esc(modal.title)}</h2>${modal.desc?`<p>${esc(modal.desc)}</p>`:''}</div><button class="close-btn" data-action="close-modal" aria-label="Закрыть">×</button></div>${modal.body}${modal.footer?`<div class="modal-footer">${modal.footer}</div>`:''}</section></div>`}
  const field=(label,name,value='',type='text',placeholder='')=>`<div class="field"><label class="label" for="f-${name}">${label}</label><input class="input" id="f-${name}" name="${name}" type="${type}" value="${esc(value||'')}" placeholder="${placeholder}" /></div>`;
  const selectField=(label,name,value,options)=>`<div class="field"><label class="label" for="f-${name}">${label}</label><select class="select" id="f-${name}" name="${name}">${options.map(o=>`<option value="${esc(o)}" ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;
  const textField=(label,name,value='',placeholder='')=>`<div class="field"><label class="label" for="f-${name}">${label}</label><textarea class="textarea" id="f-${name}" name="${name}" placeholder="${placeholder}">${esc(value||'')}</textarea></div>`;
  function petForm(p=null){const edit=!!p;openModal(edit?'Изменить питомца':'Добавить питомца',edit?'Обновите профиль. Обязательное поле отмечено *':'Заполните основные сведения. Они останутся в этом браузере.',`<form id="pet-form">${field('Имя питомца *','name',p?.name||'','text','Например, Луна')}<div class="form-row">${selectField('Вид','species',p?.species||'Собака',['Собака','Кошка','Другое'])}${field('Порода','breed',p?.breed||'','text','Если знаете')}</div><div class="form-row">${field('Дата рождения','birthDate',p?.birthDate||'','date')}${selectField('Аватар','emoji',p?.emoji||'🐕',['🐕','🐈','🐇','🐾','🦜','🐢'])}</div>${textField('Заметка','note',p?.note||'','Особенности, которые важно помнить')}<input type="hidden" name="id" value="${p?.id||''}"/><div class="modal-footer"><button type="button" class="btn btn-secondary" data-action="close-modal">Отмена</button><button class="btn btn-primary">${edit?'Сохранить':'Добавить питомца'}</button></div></form>`)}
  function eventForm(e=null){if(!state.pets.length){notify('Сначала добавьте питомца');return}const edit=!!e,p=currentPet();openModal(edit?'Изменить событие':'Новое событие',`Для питомца: ${p?.name||'не выбран'}. Содержание вводит владелец.`, `<form id="event-form">${field('Название *','title',e?.title||'','text','Например, визит к ветеринару')}${field('Дата *','date',e?.date||today,'date')}<div class="field"><label class="label" for="f-petName">Питомец</label><select class="select" name="petId" id="f-petName">${state.pets.map(x=>`<option value="${x.id}" ${(e?.petId||p?.id)===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>${textField('Пояснение','note',e?.note||'','Добавьте заметку')}<div class="field"><label class="label" for="f-repeat">Повтор</label><select class="select" id="f-repeat" name="repeatDays"><option value="0" ${!e?.repeatDays?'selected':''}>Без повтора</option><option value="7" ${e?.repeatDays===7?'selected':''}>Каждую неделю</option><option value="30" ${e?.repeatDays===30?'selected':''}>Каждые 30 дней</option><option value="90" ${e?.repeatDays===90?'selected':''}>Каждые 90 дней</option></select><div class="help">Повтор — только напоминание. Медицинский график обсудите с ветеринаром.</div></div><input type="hidden" name="id" value="${e?.id||''}"/><div class="modal-footer"><button type="button" class="btn btn-secondary" data-action="close-modal">Отмена</button><button class="btn btn-primary">Сохранить событие</button></div></form>`)}
  function foodForm(e=null){if(!state.pets.length){notify('Сначала добавьте питомца');return}const p=currentPet();openModal(e?'Изменить запись':'Запись питания',`Дневник ${p?.name||'питомца'}.`, `<form id="food-form">${field('Продукт или корм *','food',e?.food||'','text','Название корма или продукта')}${field('Дата *','date',e?.date||today,'date')}<div class="field"><label class="label" for="f-foodpet">Питомец</label><select class="select" id="f-foodpet" name="petId">${state.pets.map(x=>`<option value="${x.id}" ${(e?.petId||p?.id)===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>${textField('Заметка','note',e?.note||'','Например, самочувствие после кормления')}<input type="hidden" name="id" value="${e?.id||''}"/><div class="modal-footer"><button type="button" class="btn btn-secondary" data-action="close-modal">Отмена</button><button class="btn btn-primary">Сохранить</button></div></form>`)}
  function fileForm(kind){if(!state.pets.length){notify('Сначала добавьте питомца');return}const isPhoto=kind==='photo';openModal(isPhoto?'Добавить фото':'Добавить документ',`Файл будет сохранён только в текущем браузере.`, `<form id="file-form" data-kind="${kind}"><div class="field"><label class="label" for="f-file">${isPhoto?'Фотография':'Файл'}</label><input class="input" id="f-file" type="file" ${isPhoto?'accept="image/*"':''} required /><div class="help">${isPhoto?'Поддерживаются изображения.':'Не загружайте конфиденциальные документы на чужих устройствах.'}</div></div><div class="field"><label class="label" for="f-filepet">Питомец</label><select class="select" id="f-filepet">${state.pets.map(x=>`<option value="${x.id}" ${x.id===currentPet()?.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>${!isPhoto?`<div class="field"><label class="label" for="f-kind">Тип документа</label><select class="select" id="f-kind"><option>Ветеринарный документ</option><option>Анализы</option><option>Страховка</option><option>Другое</option></select></div>`:''}<div class="modal-footer"><button type="button" class="btn btn-secondary" data-action="close-modal">Отмена</button><button class="btn btn-primary">Сохранить локально</button></div></form>`)}
  function showFoodResult(raw){const box=document.getElementById('food-result');if(!box)return;const product=raw.trim().toLocaleLowerCase('ru').replace(/[.,!?]+$/,'');if(!product){box.innerHTML='';return}if(product==='колбаса'||product==='сосиска'||product==='сосиски'){box.innerHTML=`<div class="result-box"><div class="result-title"><span class="badge">!</span><span>Вредно · осторожное предупреждение</span></div><p>В демонстрационном примере колбаса отмечена как нежелательный продукт для собаки. Риск зависит от состава и количества; база не подтверждена ветеринарными источниками и не ставит диагноз.</p><p><b>Что делать:</b> проверьте состав и наблюдайте за питомцем. При симптомах или сомнениях свяжитесь с ветеринарной клиникой.</p><p class="article-meta">Источник: демонстрационное требование к прототипу · ветеринарная проверка не выполнена</p></div>`}else{box.innerHTML=`<div class="result-box safe"><div class="result-title"><span class="badge" style="background:#e8eee7">?</span><span>Нет проверенной записи</span></div><p>«${esc(raw.trim())}» не найдено в маленькой демонстрационной базе. Это не означает, что продукт безопасен. Уточните у ветеринара, особенно если питомец уже съел его.</p></div>`}}
  function go(routeName){route=routeName;render();window.scrollTo({top:0,behavior:'smooth'})}
  function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name||'файл';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200)}
  function confirmBox(titleText,desc,onYes,label='Удалить'){openModal(titleText,desc,`<div class="modal-footer"><button class="btn btn-secondary" data-action="close-modal">Отмена</button><button class="btn btn-danger" data-action="confirm-action">${label}</button></div>`);document.querySelector('[data-action="confirm-action"]')?.addEventListener('click',()=>{closeModal();onYes()},{once:true})}
  document.addEventListener('click',async e=>{const nav=e.target.closest('[data-route]');if(nav){go(nav.dataset.route);return}const sub=e.target.closest('[data-sub]');if(sub){subroute=sub.dataset.sub;go('care');return}const ex=e.target.closest('[data-food-example]');if(ex){go('food');setTimeout(()=>{const inp=document.getElementById('food-search');if(inp){inp.value=ex.dataset.foodExample;showFoodResult(inp.value)}},10);return}const b=e.target.closest('[data-action]');if(!b)return;const act=b.dataset.action,id=b.dataset.id;switch(act){case'close-modal':closeModal();break;case'backdrop':if(e.target===b)closeModal();break;case'add-pet':petForm();break;case'edit-pet':petForm(petById(id));break;case'delete-pet':{const p=petById(id);confirmBox('Удалить профиль питомца?',`Профиль «${p?.name||''}» и связанные с ним записи, файлы и события будут удалены.`,async()=>{const fileItems=[...state.documents,...state.photos].filter(x=>x.petId===id);for(const x of fileItems)try{await fileDB.del(x.fileId)}catch{}state.pets=state.pets.filter(x=>x.id!==id);state.events=state.events.filter(x=>x.petId!==id);state.foodEntries=state.foodEntries.filter(x=>x.petId!==id);state.documents=state.documents.filter(x=>x.petId!==id);state.photos=state.photos.filter(x=>x.petId!==id);state.activePetId=state.pets[0]?.id||null;save();render();notify('Профиль удалён')});break}case'select-pet':state.activePetId=id;save();render();notify('Питомец выбран');break;case'add-event':eventForm();break;case'edit-event':eventForm(state.events.find(x=>x.id===id));break;case'event-done':{const ev=state.events.find(x=>x.id===id);if(ev){ev.done=true;if(ev.repeatDays){state.events.push({...ev,id:uid(),date:addDays(ev.date,Number(ev.repeatDays)),done:false,demo:false})}save();render();notify(ev.repeatDays?'Событие завершено, создан следующий повтор':'Событие отмечено как выполненное')}break}case'add-food':foodForm();break;case'edit-food':foodForm(state.foodEntries.find(x=>x.id===id));break;case'delete-food':confirmBox('Удалить запись?', 'Запись дневника будет удалена.',()=>{state.foodEntries=state.foodEntries.filter(x=>x.id!==id);save();render()});break;case'add-document':fileForm('document');break;case'add-photo':fileForm('photo');break;case'delete-document':case'delete-photo':confirmBox('Удалить файл?','Файл будет удалён из локального хранилища.',async()=>{try{await fileDB.del(b.dataset.file)}catch{}if(act==='delete-document')state.documents=state.documents.filter(x=>x.id!==id);else state.photos=state.photos.filter(x=>x.id!==id);save();render();notify('Файл удалён')});break;case'download-file':try{const blob=await fileDB.get(id);if(blob)downloadBlob(blob,b.dataset.name);else notify('Файл не найден в хранилище')}catch{notify('Не удалось открыть локальный файл')}break;case'community-request':if(!state.community.requests.includes(id)){state.community.requests.push(id);save();render();notify('Демо-запрос сохранён только у вас')}break;case'community-block':confirmBox('Скрыть демо-карточку?','Она исчезнет из списка на этом устройстве.',()=>{state.community.blocked.push(id);save();render();notify('Карточка скрыта')},'Скрыть');break;case'community-report':openModal('Жалоба на карточку-пример','Жалобы в демонстрации не отправляются.',`<form id="report-form"><div class="field"><label class="label" for="report-reason">Причина</label><select class="select" id="report-reason"><option>Неподходящий контент</option><option>Спам</option><option>Нарушение приватности</option><option>Другое</option></select></div>${textField('Пояснение (необязательно)','report-note','','Опишите проблему')}<div class="modal-footer"><button type="button" class="btn btn-secondary" data-action="close-modal">Отмена</button><button class="btn btn-primary">Сохранить локально</button></div></form>`);break;case'vet-demo':openModal('Демо-переписка','Автоматический пример, не настоящий врач.',`<div class="message">Здравствуйте! Это демонстрационный экран. Здесь нет специалиста и ответы не обрабатываются.<time>Сейчас · пример</time></div><div class="notice">При тревожных симптомах свяжитесь с ветеринарной клиникой напрямую.</div><button class="btn btn-secondary" style="margin-top:14px" data-action="close-modal">Понятно</button>`);break;case'open-template':openTemplate(Number(id));break;case'save-city':{const city=document.getElementById('manual-city')?.value.trim()||'';state.settings.city=city;save();notify(city?'Город сохранён локально':'Город очищен');break}case'request-location':requestLocation();break;case'export-data':exportData();break;case'reset-data':confirmBox('Сбросить все данные?','Локальные профили, записи и настройки будут удалены. Файлы в IndexedDB тоже будут очищены.',async()=>{try{const d=await indexedDB.open('lapka-local-files',1);d.onsuccess=()=>{const tx=d.result.transaction('files','readwrite');tx.objectStore('files').clear()}}catch{}localStorage.removeItem(KEY);state=demoState();save();go('home');notify('Демо-данные восстановлены')},'Сбросить');break;case'community-rules':openModal('Правила сообщества','В этой сборке нет реального сообщества.',`<div class="notice">Не публикуйте точный адрес, телефон, личную почту, документы и сведения о расписании прогулок. Не отправляйте деньги незнакомым людям. Для первой встречи выбирайте общественное место, сообщите близкому человеку о планах. Блокировка и жалоба в этой демо-версии работают только локально.</div><div class="modal-footer"><button class="btn btn-primary" data-action="close-modal">Понятно</button></div>`);break;default:break}});
  document.addEventListener('change',e=>{if(e.target.matches('#top-pet-select,#hero-pet-select')){state.activePetId=e.target.value;save();render()}if(e.target.matches('[data-setting]')){state.settings[e.target.dataset.setting]=e.target.checked;save();notify('Настройка сохранена локально')}});
  document.addEventListener('input',e=>{if(e.target.id==='food-search')showFoodResult(e.target.value);if(e.target.id==='knowledge-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('.knowledge-item').forEach(x=>x.hidden=!x.dataset.search.includes(q))}if(e.target.id==='place-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('.place-item').forEach(x=>x.hidden=!x.dataset.search.includes(q))}});
  document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;const data=new FormData(f);const formId=f.getAttribute('id');if(formId==='pet-form'){const name=String(data.get('name')||'').trim();if(!name){notify('Укажите имя питомца');return}const id=String(data.get('id')||'');const obj={id:id||uid(),name,species:data.get('species'),breed:String(data.get('breed')||'').trim(),birthDate:data.get('birthDate')||'',note:String(data.get('note')||'').trim(),emoji:data.get('emoji')||'🐾',demo:false};if(id)state.pets=state.pets.map(x=>x.id===id?{...x,...obj}:x);else{state.pets.push(obj);state.activePetId=obj.id}save();closeModal();render();notify(id?'Профиль обновлён':'Питомец добавлен')}
    else if(formId==='event-form'){const title=String(data.get('title')||'').trim(),date=data.get('date');if(!title||!date){notify('Заполните название и дату');return}const id=String(data.get('id')||'');const obj={id:id||uid(),petId:data.get('petId'),title,date,note:String(data.get('note')||'').trim(),repeatDays:Number(data.get('repeatDays')||0),done:false,demo:false};if(id)state.events=state.events.map(x=>x.id===id?{...x,...obj}:x);else state.events.push(obj);save();closeModal();render();notify(id?'Событие обновлено':'Событие добавлено')}
    else if(formId==='food-form'){const food=String(data.get('food')||'').trim(),date=data.get('date');if(!food||!date){notify('Укажите продукт и дату');return}const id=String(data.get('id')||'');const obj={id:id||uid(),petId:data.get('petId'),food,date,note:String(data.get('note')||'').trim(),demo:false};if(id)state.foodEntries=state.foodEntries.map(x=>x.id===id?{...x,...obj}:x);else state.foodEntries.unshift(obj);save();closeModal();render();notify(id?'Запись обновлена':'Запись добавлена')}
    else if(f.id==='file-form'){const file=document.getElementById('f-file').files[0];if(!file){notify('Выберите файл');return}if(file.size>20*1024*1024){notify('Максимальный размер файла — 20 МБ');return}const fileId=uid();try{await fileDB.put(fileId,file);const kind=f.dataset.kind;const obj={id:uid(),fileId,name:file.name,size:file.size,date:today,petId:document.getElementById('f-filepet').value,kind:document.getElementById('f-kind')?.value||'',mime:file.type};if(kind==='photo')state.photos.unshift(obj);else state.documents.unshift(obj);save();closeModal();render();notify('Файл сохранён локально')}catch(err){console.error(err);notify('Не удалось сохранить файл в браузере')}}
    else if(f.id==='report-form'){state.community.reports.push({reason:document.getElementById('report-reason').value,note:document.getElementById('f-report-note').value,createdAt:new Date().toISOString()});save();closeModal();notify('Демо-жалоба сохранена локально')}
  });
  function openTemplate(i){const t=[['Подготовка к визиту к ветеринару','Соберите наблюдения и вопросы, которые хотите обсудить со специалистом.','Дата визита · вопросы · наблюдения · документы'],['Список для поездки','Проверьте привычные вещи и документы перед поездкой.','Документы · корм · вещи · контакт клиники'],['Знакомство на прогулке','Согласуйте безопасную встречу в общественном месте.','Время · общественное место · пожелания'],['Профиль питомца','Соберите основные сведения о питомце.','Имя · порода · особенности · заметки']][i];if(!t)return;openModal(t[0],t[1],`<div class="notice">Поля: ${esc(t[2])}</div><form id="template-form">${textField('Моя заметка','template-note','','Заполните здесь свои пункты')}<div class="modal-footer"><button class="btn btn-secondary" type="button" data-action="close-modal">Закрыть</button><button class="btn btn-primary">Сохранить в заметки</button></div></form>`)}
  function requestLocation(){if(!navigator.geolocation){notify('Геолокация недоступна. Город можно указать вручную.');return}openModal('Зачем нужна геолокация?','Только с вашего разрешения: чтобы определить примерный город для мест. Публичный поиск включается отдельно.',`<div class="notice">Точная координата не будет показана другим людям. Для сообщества требуется отдельное согласие; по умолчанию все переключатели приватны.</div><div class="modal-footer"><button class="btn btn-secondary" data-action="close-modal">Не сейчас</button><button class="btn btn-primary" data-action="confirm-location">Разрешить определить город</button></div>`);modalRoot.querySelector('[data-action="confirm-location"]')?.addEventListener('click',()=>{closeModal();navigator.geolocation.getCurrentPosition(pos=>{const lat=Math.round(pos.coords.latitude*10)/10,lon=Math.round(pos.coords.longitude*10)/10;state.settings.locationApprox=`${lat}, ${lon}`;state.settings.locationGranted=true;save();notify('Получена примерная координата; город нужно указать вручную')},()=>notify('Разрешение не получено. Можно продолжить без геолокации.'),{maximumAge:600000,timeout:8000})},{once:true})}
  function exportData(){const safe={...state,settings:{...state.settings,locationApprox:undefined},exportedAt:new Date().toISOString(),note:'Локальный экспорт прототипа. Вложения файлов не включены.'};downloadBlob(new Blob([JSON.stringify(safe,null,2)],{type:'application/json'}),'lapka-data.json');notify('Экспорт подготовлен')}
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal)closeModal();if(e.key==='Tab'&&modal){const els=[...modalRoot.querySelectorAll('button,input,select,textarea,[tabindex]:not([tabindex="-1"])')].filter(x=>!x.disabled);if(!els.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
  document.addEventListener('submit',e=>{if(e.target.id==='food-check-form'){e.preventDefault();showFoodResult(document.getElementById('food-search').value)}if(e.target.id==='template-form'){e.preventDefault();const value=document.getElementById('f-template-note').value.trim();if(value){state.foodEntries;const notes=JSON.parse(localStorage.getItem('lapka-notes')||'[]');notes.push({text:value,date:today});localStorage.setItem('lapka-notes',JSON.stringify(notes));notify('Заметка сохранена локально')}closeModal()}});
  function intro(){if(state.settings.onboardingDone)return;openModal('Забота о питомце — в одном месте','Создайте профиль, ведите таймлайн и храните записи локально. Геолокация и публичный профиль выключены.',`<div class="notice"><b>Геолокация нужна</b> только для примерного подбора мест. Точную GPS-точку не показываем другим. Для сообщества потребуется отдельное согласие. Можно продолжить без геолокации.</div><div class="notice">Это локальный прототип: настоящие аккаунт, ветеринарный чат, карта и каталог не подключены.</div><div class="modal-footer"><button class="btn btn-secondary" data-action="intro-location">Сначала настроить геолокацию</button><button class="btn btn-primary" data-action="intro-continue">Продолжить без геолокации</button></div>`);modalRoot.querySelector('[data-action="intro-continue"]')?.addEventListener('click',()=>{state.settings.onboardingDone=true;save();closeModal();notify('Добро пожаловать в Лапку')},{once:true});modalRoot.querySelector('[data-action="intro-location"]')?.addEventListener('click',()=>{state.settings.onboardingDone=true;save();closeModal();requestLocation()},{once:true})}
  render();intro();
})();
